import json,html,os
R=os.path.dirname(os.path.abspath(__file__));D=json.load(open(f'{R}/data/tools.json'))
ch=json.load(open(f'{R}/data/changes.json')) if os.path.exists(f'{R}/data/changes.json') else []
e=lambda s:html.escape(str(s))
CSS="body{font:15px system-ui;max-width:1100px;margin:auto;padding:1em}table{border-collapse:collapse;width:100%}td,th{border-bottom:1px solid #ddd;padding:6px;text-align:left}nav a{margin-right:1em}.note{background:#f6f6f6;padding:.6em}"
def page(t,b,p=''):return f"<!doctype html><meta charset=utf-8><meta name=viewport content='width=device-width'><title>{e(t)} | AgentQA</title><style>{CSS}</style><nav><a href={p}index.html><b>AgentQA</b></a><a href={p}compare.html>Compare</a><a href={p}changes.html>What changed</a><a href={p}about.html>About & disclosure</a></nav>{b}<hr><form class=note onsubmit='alert(\"Newsletter coming soon\");return false'>Weekly AI-testing tool changes: <input type=email placeholder=you@example.com disabled> <button disabled>Subscribe (coming soon)</button></form><p><small>Facts from vendors' public pages; check source links. No paid placements yet.</small></p>"
yn=lambda v:'yes' if v else ('no' if v is False else '?')
rows=''.join(f"<tr data-cat='{e(t['category'])}' data-os='{yn(t['open_source'])}' data-free='{yn(t['free_tier'])}'><td><input type=checkbox value={t['slug']}></td><td><a href=tools/{t['slug']}.html>{e(t['name'])}</a></td><td>{e(t['category'])}</td><td>{e(', '.join(t['tests']))}</td><td>{yn(t['free_tier'])}</td><td>{yn(t['open_source'])}</td><td>{t['last_checked']}</td></tr>" for t in D)
idx=f"""<h1>AI test-automation tools & agents</h1><p>{len(D)} tools tracked.</p><input id=q placeholder='Search…'> <select id=os><option value=''>Open source: any<option>yes<option>no</select> <select id=fr><option value=''>Free tier: any<option>yes<option>no<option>?</select> <button onclick="location='compare.html#'+[...document.querySelectorAll('input:checked')].map(c=>c.value).join(',')">Compare selected</button>
<table><thead><tr><th></th><th>Tool</th><th>Category</th><th>Tests</th><th>Free tier</th><th>Open source</th><th>Checked</th></tr></thead><tbody id=tb>{rows}</tbody></table>
<script>function f(){{let q=document.getElementById('q').value.toLowerCase(),o=document.getElementById('os').value,r=document.getElementById('fr').value;for(const t of document.querySelectorAll('#tb tr'))t.hidden=!(t.textContent.toLowerCase().includes(q)&&(!o||t.dataset.os==o)&&(!r||t.dataset.free==r))}}['q','os','fr'].forEach(i=>document.getElementById(i).oninput=f)</script>"""
os.makedirs(f'{R}/site/tools',exist_ok=True);w=lambda p,s:open(f'{R}/site/{p}','w').write(s)
w('index.html',page('Tools',idx))
for t in D:
  b=f"<h1>{e(t['name'])}</h1><table>"+''.join(f"<tr><th>{k}</th><td>{e(', '.join(v) if isinstance(v,list) else yn(v) if v in (True,False,None) else v)}</td></tr>" for k,v in t.items() if k!='slug')+f"</table><p><a href='{e(t['url'])}' rel=nofollow>Visit site</a> · <a href='{e(t['source'])}'>Source</a></p>"
  w(f"tools/{t['slug']}.html",page(t['name'],b,'../'))
w('data.json',json.dumps(D))
w('compare.html',page('Compare',"<h1>Side-by-side compare</h1><p>Pick tools on the home page, or edit the URL hash (slugs, comma-separated).</p><div id=c></div><script>fetch('data.json').then(r=>r.json()).then(d=>{let s=location.hash.slice(1).split(',').filter(Boolean);let t=d.filter(x=>s.includes(x.slug));if(!t.length)t=d.slice(0,3);let k=['category','tests','pricing','free_tier','open_source','integrations','last_checked','source'];document.getElementById('c').innerHTML='<table><tr><th></th>'+t.map(x=>'<th>'+x.name+'</th>').join('')+'</tr>'+k.map(f=>'<tr><th>'+f+'</th>'+t.map(x=>'<td>'+(Array.isArray(x[f])?x[f].join(', '):x[f])+'</td>').join('')+'</tr>').join('')+'</table>'})</script>"))
w('changes.html',page('What changed',"<h1>What changed this week</h1>"+("<ul>"+''.join(f"<li>{e(c['date'])} — <b>{e(c['name'])}</b>: {e(c['what'])} (<a href='{e(c['url'])}'>page</a>)</li>" for c in ch[::-1][:50])+"</ul>" if ch else "<p>No changes detected yet. Baseline captured 2026-10-16.</p>")))
w('about.html',page('About',"<h1>About & sponsor disclosure</h1><p>AgentQA is an independent directory of AI test-automation tools. Data comes from each vendor's public pages and is re-checked automatically.</p><p class=note><b>Disclosure (placeholder):</b> We currently have no sponsors and no affiliate links. If that changes, sponsored listings will be clearly labeled 'Sponsored' and will never change factual data or ordering of non-sponsored entries.</p>"))
print('built',len(D))
